<script setup lang="ts">
import {hostModes} from './hostBilling'
const props=defineProps<{draft:Record<string,any>,available?:Record<string,any>[],fresh?:boolean}>()
function unitChange(e:Event){const n=(e.target as HTMLSelectElement).value;if(n===props.draft.unit)return;const old=props.draft.unit==='GB'?1e9:1073741824,next=n==='GB'?1e9:1073741824;props.draft.quota=props.draft.quota*old/next;props.draft.initial_used=props.draft.initial_used*old/next;props.draft.unit=n}
</script>
<template><div class="fields host-billing-fields"><label>套餐流量单位<select :value="draft.unit" @change="unitChange"><option value="GB">GB（十进制，1 GB = 10⁹ B）</option><option value="GiB">GiB（1 GiB = 2³⁰ B）</option></select></label><label>套餐额度（{{draft.unit}}，0 为不限）<input v-model.number="draft.quota" aria-label="主机流量额度" type="number" min="0" max="8000000" step="0.001" required></label><label>主机计费方式<select v-model="draft.mode" aria-label="主机计费方式"><option v-for="(name,key) in hostModes" :key="key" :value="key">{{name}}</option></select></label><label>自动重置<select v-model="draft.auto_reset"><option :value="true">每月指定日 · 北京时间</option><option :value="false">不自动重置</option></select></label><label v-if="draft.auto_reset">每月重置日<input v-model.number="draft.reset_day" type="number" min="1" max="31" required><small>下个月同日重置；缺日取月末，后续仍保留原设定日。</small></label><label v-if="fresh">运营商当前已用（{{draft.unit}}，可选）<input v-model.number="draft.initial_used" type="number" min="0" step="0.001"><small>作为起始校准值，加上接入后的网卡计量。</small></label></div><details v-if="available?.length" class="interface-selection"><summary>选择计量网卡 · {{draft.interfaces.length?'手动 '+draft.interfaces.join('、'):'自动外网网卡'}}</summary><button type="button" class="text-button" @click="draft.interfaces=[]">使用自动选择</button><div class="choice-list"><label v-for="n in available" :key="n.name"><input v-model="draft.interfaces" type="checkbox" :value="n.name">{{n.name}} <small>{{n.uplink?'默认外网网卡':'不在自动计量范围'}}</small></label></div></details><p class="form-note">统计系统网卡真实 RX/TX，包含代理、FRP、下载及其他主机流量。默认不重复计算 Docker/veth/TUN；可连接后指定网卡。与运营商账单对齐时，请确认单位、计费方向并校准已用量。实时值约 10 秒采样、页面 30 秒刷新；断报时显示采样时间。</p></template>
<style scoped>.interface-selection{padding:12px;border:1px solid var(--border);border-radius:10px;margin:12px 0}.interface-selection summary{cursor:pointer;font-size:12px}.host-billing-fields small{color:var(--muted);line-height:1.6}</style>
